    ("code", ("function resolveQrBaseUrl({ baseUrl, originHint } = {}) {\n  if (baseUrl) {\n    const normalized = normalizeOrigin(baseUrl);\n    if (!normalized) {\n      throw new ApiError(400, 'VALIDATION_ERROR', 'base_url must be a valid http(s) URL');\n    }\n    return normalized;\n  }\n  if (config.publicBaseUrl && !isLocalUrl(config.publicBaseUrl)) {\n    return config.publicBaseUrl.replace(/\\/$/, '');\n  }\n  if (originHint) {\n    const origin = normalizeOrigin(originHint);\n    if (origin) return origin;\n  }\n  return config.publicBaseUrl.replace(/\\/$/, '');\n}", "B.2.1. Chọn địa chỉ gốc cho mã QR (server/src/services/mediaService.js)")),
    ("code", ("const seconds = Number(duration) > 0\n  ? Math.round(Number(duration))\n  : measureAudioDuration(file_url);\nconst existing = await getAudioForTranslation(translationId);\nif (existing) {\n  return db.getOne(\n    `UPDATE audio_guides SET file_url=$2, duration=$3, file_size=$4, mime_type=$5, source=$6\n     WHERE id=$1 RETURNING *`,\n    [existing.id, file_url, seconds, file_size, mime_type, source]\n  );\n}", "B.2.2. Ghi đè tệp audio theo bản dịch và đo thời lượng khi thiếu (server/src/services/mediaService.js)")),
    ("code", ("const freeMatch = await db.getOne(\n  `SELECT 1 FROM guest_sessions WHERE id = $1 AND free_language_id = $2`,\n  [session.id, languageId]\n);\nif (freeMatch) return next();\n\nconst purchasedMatch = await db.getOne(\n  `SELECT 1 FROM language_entitlements\n   WHERE guest_session_id = $1 AND language_id = $2 AND access_type = 'purchased'`,\n  [session.id, languageId]\n);\nif (purchasedMatch) return next();", "B.2.3. Kiểm tra quyền ngôn ngữ bằng SQL (server/src/middleware/entitlement.js)")),

